WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_session FROM web_events), sessionized AS (SELECT id, event_type, page, event_time, duration_sec, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), scored AS (SELECT id, page, event_time, duration_sec, SUM(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_sum_7d, DENSE_RANK() OVER (PARTITION BY page ORDER BY island_id DESC) AS island_id_dense_rank, ROW_NUMBER() OVER (ORDER BY event_time DESC, id) AS seq_no, NTILE(3) OVER (ORDER BY island_id DESC, id) AS island_id_bucket, AVG(duration_sec) OVER (ORDER BY island_id, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS duration_sec_avg_5 FROM sessionized), cleaned AS (SELECT *, COALESCE(duration_sec, 0) AS duration_sec_filled FROM scored WHERE event_time > TO_DATE('2023-10-09')), filtered AS (SELECT id, page, event_time, duration_sec, island_id_dense_rank, island_id_bucket, duration_sec_avg_5, duration_sec_filled, GREATEST(duration_sec, duration_sec_filled) AS greatest_duration_sec_duration_sec_filled, COALESCE(page, 'UNKNOWN') AS page_clean FROM cleaned WHERE event_time >= TIMESTAMP '2023-08-01 21:00:00' AND page IS NOT DISTINCT FROM '/checkout') SELECT id, page, island_id_dense_rank, island_id_bucket, duration_sec_avg_5, duration_sec_filled, greatest_duration_sec_duration_sec_filled, page_clean FROM filtered ORDER BY island_id_dense_rank, island_id_bucket DESC;
